verification_commands.ac1:
set -u
F=docs/criteria/scoring_map/delivery.md
test -f "$F" || { echo "ac1 RED: $F missing - this card's whole deliverable is this file"; exit 1; }
S=$(tr -d '\r' < "$F" | awk '/^## Deployment[[:space:]]*$/{f=1;next} f&&/^## /{exit} f')
[ -n "$S" ] || { echo "ac1 RED: no '## Deployment' section - the rubric grades a deploy at a public URL or a clear demo"; exit 1; }
CL=$(printf "%s\n" "$S" | sed -n 's/^- Claim:[[:space:]]*\([0-9][0-9]*\)\/\([0-9][0-9]*\)[[:space:]]*$/\1 \2/p')
[ -n "$CL" ] || { echo "ac1 RED: no '- Claim: N/M' line in the exact record format"; exit 1; }
set -- $CL
[ "$1" -le "$2" ] && [ "$2" = "2" ] || { echo "ac1 RED: the Deployment claim '$1/$2' is malformed or does not use the rubric maximum 2"; exit 1; }
printf "%s\n" "$S" | grep -qE "^- Reason: ..*" || { echo "ac1 RED: no measured Reason line"; exit 1; }
EP=$(printf "%s\n" "$S" | sed -n 's/^- First entry point:[[:space:]]*`\([^`]*\)`[[:space:]]*$/\1/p')
[ -n "$EP" ] || { echo "ac1 RED: no single backticked First entry point"; exit 1; }
[ "$(printf "%s\n" "$S" | grep -cE '^- First entry point:')" = "1" ] || { echo "ac1 RED: more than one First entry point line"; exit 1; }
case "$EP" in http*|https*) : ;; *) test -e "$EP" || { echo "ac1 RED: first entry point '$EP' does not exist on this tree"; exit 1; } ;; esac
printf "%s\n" "$S" | grep -qE 'expense-tracker-dashboard-1qtu[.]onrender[.]com' || { echo "ac1 RED: the record does not name the real hosted address - the rubric clause is 'deployed at a public URL' and the address is the claim; a different or fabricated host is a FAIL"; exit 1; }
printf "%s\n" "$S" | grep -qE 'render[.]yaml' || { echo "ac1 RED: the record never names render.yaml - the infrastructure-as-code half of the deployment claim lives there"; exit 1; }
printf "%s\n" "$S" | grep -qE 'ops/deployment-health[.]md|/api/v1/health' || { echo "ac1 RED: the record names no health evidence - 'deployed' without a health endpoint is an assumption, and the health URL is the 30-second check"; exit 1; }
printf "%s\n" "$S" | grep -qE "2026-[0-9]{2}-[0-9]{2}" || { echo "ac1 RED: the record does not date-stamp when the live host was verified - the static-serving fix was verified on 2026-10-22 (WAL 1265) and an undated liveness claim ('verified', 'live', 'working') is exactly the stale-premise failure this milestone exists to remove"; exit 1; }
printf "%s\n" "$S" | grep -qE "2026-10-22" || { echo "ac1 RED: the date-stamped liveness is not 2026-10-22, the date the groom measured and WAL 1265 records - if the host was re-verified later, re-groom this record against the new WAL row rather than editing the old date"; exit 1; }
MISS=""
for p in $(printf "%s\n" "$S" | grep -E '^- (Evidence|Deep dive):' | tr '`,' '\n\n' | grep -E '^[A-Za-z0-9].*/' ); do
  test -e "$p" || MISS="$MISS $p"
done
[ -z "${MISS// /}" ] || { echo "ac1 RED: evidence paths that do not exist:$MISS"; exit 1; }
echo "ac1 GREEN: DEPLOYMENT recorded - claim $1/$2, one existing first entry point ($EP), the real hosted address, render.yaml and the health evidence named, and the liveness claim date-stamped"

verification_commands.ac2:
set -u
F=docs/criteria/scoring_map/delivery.md
test -f "$F" || { echo "ac2 RED: $F missing"; exit 1; }
S=$(tr -d '\r' < "$F" | awk '/^## CI\/CD[[:space:]]*$/{f=1;next} f&&/^## /{exit} f')
[ -n "$S" ] || { echo "ac2 RED: no '## CI/CD' section - the rubric names this dimension with a 0-3 scale"; exit 1; }
CL=$(printf "%s\n" "$S" | sed -n 's/^- Claim:[[:space:]]*\([0-9][0-9]*\)\/\([0-9][0-9]*\)[[:space:]]*$/\1 \2/p')
[ -n "$CL" ] || { echo "ac2 RED: no '- Claim: N/M' line in the exact record format"; exit 1; }
set -- $CL
[ "$2" = "3" ] || { echo "ac2 RED: the CI/CD maximum is 3 per the grading rubric, not $2 - do not invent a scale"; exit 1; }
[ "$1" = "2" ] || { echo "ac2 RED: the CI/CD claim is $1 of 3, but the operator's chosen strategy is 'stable 2 + fight for 3' = claim 2/3 with the gap priced; claiming 3 would assert a dev environment that does not exist, and claiming 1 would discard the automatic CD that deploy.yml really runs"; exit 1; }
EP=$(printf "%s\n" "$S" | sed -n 's/^- First entry point:[[:space:]]*`\([^`]*\)`[[:space:]]*$/\1/p')
[ -n "$EP" ] || { echo "ac2 RED: no single backticked First entry point"; exit 1; }
case "$EP" in http*|https*) : ;; *) test -e "$EP" || { echo "ac2 RED: first entry point '$EP' does not exist"; exit 1; } ;; esac
for w in ci deploy e2e; do
  printf "%s\n" "$S" | grep -qE "$w[.]yml" || { echo "ac2 RED: the record never names $w.yml - all three shipped pipelines are evidence for this dimension and omitting one understates the project"; exit 1; }
done
printf "%s\n" "$S" | grep -qiE "pull_request|pull request|PR" || { echo "ac2 RED: the record never states that CI runs on pull requests - that is the FIRST point of the 0-3 scale, and ci.yml really carries a pull_request trigger"; exit 1; }
printf "%s\n" "$S" | grep -qiE "workflow_run|after[[:space:]]+(the[[:space:]]+)?(E2E|e2e)|automatic" || { echo "ac2 RED: the record never states the automatic CD trigger - deploy.yml fires on workflow_run completion of E2E and that is the SECOND point"; exit 1; }
printf "%s\n" "$S" | grep -qiE "health" || { echo "ac2 RED: the record says nothing about the post-deploy health verification - deploy.yml's bounded retry is what makes 'CD' mean 'deployed and verified', not 'curl fired'"; exit 1; }
printf "%s\n" "$S" | grep -qE 'permissions|contents:[[:space:]]*read|least[[:space:]-]privilege' || { echo "ac2 RED: the record never mentions the least-privilege token - all three workflows set permissions: contents: read and that is a graded property of the pipeline"; exit 1; }
MISS=""
for p in $(printf "%s\n" "$S" | grep -E '^- (Evidence|Deep dive):' | tr '`,' '\n\n' | grep -E '^[A-Za-z0-9].*/' ); do
  test -e "$p" || MISS="$MISS $p"
done
[ -z "${MISS// /}" ] || { echo "ac2 RED: evidence paths that do not exist:$MISS"; exit 1; }
# the claim must be the measured position, not a padded one
if printf "%s\n" "$S" | grep -qiE "claim:? *3/3|3 of 3|full score on CI/CD"; then
  echo "ac2 RED: the section pads CI/CD to 3/3 somewhere - the third point requires CD to dev AND a manual production deploy, and no dev environment exists"; exit 1
fi
echo "ac2 GREEN: CI/CD recorded at the measured position - claim 2/3, all three shipped pipelines and their real triggers named (PR tests, workflow_run auto-CD, main-only E2E), post-deploy health verification and least-privilege tokens stated, every evidence path resolves, and no 3/3 padding anywhere"

verification_commands.ac3:
set -u
F=docs/criteria/scoring_map/delivery.md
test -f "$F" || { echo "ac3 RED: $F missing"; exit 1; }
S=$(tr -d '\r' < "$F" | awk '/^## CI\/CD[[:space:]]*$/{f=1;next} f&&/^## /{exit} f')
[ -n "$S" ] || { echo "ac3 RED: no '## CI/CD' section"; exit 1; }
printf "%s\n" "$S" | grep -qE 'promote[.]yml' || { echo "ac3 RED: the record never names promote.yml - t119's human-gated manual deploy pipeline is the 'fight for 3' half of the operator's strategy and the record must point at it"; exit 1; }
# promote.yml is NAMED here but must never appear in an Evidence or Deep dive path list:
# this card merges BEFORE t119 (the milestone's dispatch order, WAL 1268), so a path leg
# that test -e'd it would be RED on the very tree this record lands on. The prose names
# it as 'the milestone's t119 pipeline', which stays true after t119 merges too.
printf "%s\n" "$S" | grep -E '^- (Evidence|Deep dive):' | grep -qE 'promote[.]yml' && { echo "ac3 RED: promote.yml sits in an Evidence or Deep dive path list while this record lands before t119 merges - name it in Reason or Gap prose only, or the path leg of ac2 would be a pointer to a file that is not there"; exit 1; }
GPRO=$(printf "%s\n" "$S" | grep -cE "t119")
[ "$GPRO" -ge 1 ] || { echo "ac3 RED: promote.yml is named without its t119 context - the reader needs the card that ships it, and the phrasing must stay true on both sides of the t119 merge"; exit 1; }
printf "%s\n" "$S" | grep -qiE 'environment:[[:space:]]*production|"production" environment|GitHub Environment[^.]{0,40}production' || { echo "ac3 RED: the record never names the production GitHub Environment - the human gate is a real artifact and the operator created it; hiding it under-claims the project"; exit 1; }
printf "%s\n" "$S" | grep -qiE 'workflow_dispatch|manual(ly)? trigger|manually' || { echo "ac3 RED: the record does not state that the production deploy is manually triggered - that is the third point's manual-deploy clause"; exit 1; }
printf "%s\n" "$S" | grep -qiE 'does not exist|no second|not exist|no dev[/ ]prod|single (service|environment)|same live service' || { echo "ac3 RED: the record does not state plainly that environment separation does NOT exist - the operator's instruction is explicit: the human gate DOES and the separation does not, and a reader who discovers this after awarding 3/3 has been misled"; exit 1; }
printf "%s\n" "$S" | grep -qiE 'repo Settings|repository Settings|not in git|Settings, not' || { echo "ac3 RED: the record does not disclose that the Environment is a repo-Settings artifact that cannot be verified from the tree - a claim a reader cannot check in 30 seconds at an entry point must be labelled as such"; exit 1; }
G=$(printf "%s\n" "$S" | sed -n 's/^- Gap:[[:space:]]*\(.*\)$/\1/p')
[ -n "$G" ] || { echo "ac3 RED: no '- Gap:' line - the operator's strategy is 'claim 2/3 with a priced gap', so the price must be written down, not implied by a missing third point"; exit 1; }
GL=$(printf "%s\n" "$G" | wc -w | tr -d " ")
[ "$GL" -ge 8 ] || { echo "ac3 RED: the Gap line is $GL words - too short to price anything; it must name what is missing (a second environment) and what is present (the human gate)"; exit 1; }
[ "$GL" -le 60 ] || { echo "ac3 RED: the Gap line is $GL words - the map's value is one-line comprehension; a paragraph belongs in a deep-dive doc"; exit 1; }
printf "%s\n" "$G" | grep -qiE 'environment|dev|separat|instance|service' || { echo "ac3 RED: the Gap line does not name the missing environment as the price"; exit 1; }
echo "ac3 GREEN: HONESTY PAIR RECORDED - the human gate (production Environment, workflow_dispatch, promote.yml) is claimed, the absence of environment separation is stated, its non-git provenance is disclosed, and the 2/3 price is one bounded sentence ($GL words)"
